{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/milestone-timeline.json
    Milestones on a line: the year, a tag, a title and a sentence each. Axes: layout (split: a vertical line beside a picture, stacked: a vertical line in a narrow column, row: a horizontal line of columns), tone, density.
    Props (p): id, title, lead, milestones, layout, tone, density, landmarkLabel. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_lead = ($p['lead'] ?? '')}
{var $v_milestones = ($p['milestones'] ?? null)}
{var $v_layout = ($p['layout'] ?? 'split')}
{var $v_tone = ($p['tone'] ?? 'default')}
{var $v_density = ($p['density'] ?? 'default')}
{var $v_landmarkLabel = ($p['landmarkLabel'] ?? null)}
{capture $f_8}
  {=ui_include('blocks/media-frame.latte', ['p' => ['alt' => $v_title, 'ratio' => '3/4']])|noescape}
{/capture}
{capture $c_9}
  {capture $c_7}
    {foreach ui_l($v_milestones) as $v_m}
      {capture $c_6}
        {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'row')) ? 'absolute top-0 left-0 size-2 -translate-y-1/2 rounded bg-primary' : 'absolute top-2 left-0 size-2 -translate-x-1/2 rounded bg-primary')), 'Attrs' => ui_attrs(['aria-hidden', 'true'])]])|noescape}
        {capture $c_3}
          {capture $c_1}
            {=ui_text(ui_get($v_m, ['date']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Weight' => 'semibold'], 'children' => $c_1])|noescape}
          {capture $c_2}
            {=ui_text(ui_get($v_m, ['tag']))}
          {/capture}
          {=ui_include('ui/badge/badge.latte', ['p' => ['Variant' => 'outline', 'Size' => 'sm'], 'children' => $c_2])|noescape}
        {/capture}
        {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '2', 'Align' => 'center'], 'children' => $c_3])|noescape}
        {capture $c_4}
          {=ui_text(ui_get($v_m, ['title']))}
        {/capture}
        {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(3), 'Size' => 'lg', 'Weight' => 'bold'], 'children' => $c_4])|noescape}
        {capture $c_5}
          {=ui_text(ui_get($v_m, ['text']))}
        {/capture}
        {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'sm', 'Class' => 'text-muted-foreground'], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/list/list-item.latte', ['p' => ['Class' => ui_s((ui_t(ui_eq($v_layout, 'row')) ? 'relative flex flex-col gap-2 pt-6' : 'relative flex flex-col gap-2 pl-6')), 'Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_6])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/list/list.latte', ['p' => ['Tag' => 'ol', 'Class' => ui_s((ui_t(ui_eq($v_layout, 'row')) ? 'grid grid-cols-1 gap-8 border-t border-border sm:grid-cols-2 lg:grid-cols-4' : 'flex flex-col gap-8 border-l border-border')), 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_7])|noescape}
{/capture}
{=ui_include('blocks/section-frame.latte', ['p' => ['id' => $v_id, 'title' => $v_title, 'lead' => $v_lead, 'tone' => $v_tone, 'density' => $v_density, 'layout' => (ui_t(ui_eq($v_layout, 'split')) ? 'split' : 'stack'), 'media' => ['show' => ui_eq($v_layout, 'split'), 'side' => 'start', 'align' => 'start'], 'measure' => (ui_t(ui_eq($v_layout, 'stacked')) ? '2xl' : 'default'), 'landmarkLabel' => $v_landmarkLabel, 'aside' => $f_8], 'children' => $c_9])|noescape}
